  render: () => <Stack>
      <Section title="EmptyState sizes" note="The title states what is TRUE; the body is one short line; the buttons are verb + noun. sm for a panel, md (default), lg for a whole page.">
        <div className="grid grid-cols-3 gap-4 max-lg:grid-cols-1">
          {(['sm', 'md', 'lg'] as const).map(size => <div key={size} className="rounded-card border border-hairline bg-card">
              <EmptyState size={size} icon={<Inbox />} title="Nothing in your inbox" body="New messages and mentions land here." primary={{
            label: 'Start a chat',
            onClick: () => undefined
          }} />
            </div>)}
        </div>
      </Section>
      <Section title="Variants">
        <div className="grid grid-cols-2 gap-4 max-lg:grid-cols-1">
          <div className="rounded-card border border-hairline bg-card">
            <EmptyState icon={<Search />} title="No results for “roadmap”" body="Try another word, or clear the filters." secondary={{
            label: 'Clear filters',
            onClick: () => undefined
          }} />
          </div>
          <div className="rounded-card border border-hairline bg-card">
            <EmptyState icon={<Folder />} title="No folders yet" body="Folders keep related files together." primary={<Button variant="primary" size="sm">Create a folder</Button>} secondary={{
            label: 'Upload files',
            onClick: () => undefined
          }} />
          </div>
        </div>
      </Section>
    </Stack>
